// The cliff kit (Chunky Sunshine blocks; docs/plans/cliff-kit-everywhere.md): sandstone faces on the walls, boulders at
// their foot, caps on the rims and low rock at the waterline, area by area (today the canyon climb). Every piece is a
// record (src/content/prefabs/terrain.ts) standing where its area's level puts it (./areas.ts, generated by
// dev/prefab/cliff-kit.ts), one instance batch a piece an area. Local scenery: no state, no sync. Its solids are client
// walk colliders. A solid never appears around a player at mount: the pieces Buddy stands in then wait, neither drawn nor
// solid, as one set, until Buddy is clear of them all (src/place/clearance.ts, waiting only: a view moves no bodies
// outside the prefab door). After mount the pieces are ordinary static solids.
import { terrainKitGeometry } from './geometry.ts';
import { createOwnedView } from '../../render/owned-view.ts';
import { me } from '../../player/player.ts';
import { createPrefabBatch, instantiate, liftOrWait } from '../../prefab/instantiate.ts';
import { definitions } from '../../prefab/catalogue.ts';
import { loadLevelArtifact } from '../../prefab/validate.ts';
import { setTerrainKit } from '../../prefab/builders/terrain-kit.ts';
import type { PrefabKey } from '../../prefab/types.ts';
import { KIT_AREAS } from './areas.ts';
import { ringIslandNear } from '../ring-island/state.ts';

export async function createTerrainKitView() {
  const owner = createOwnedView();
  owner.root.name = 'terrain-kit';
  try {
    return await build(owner);
  } catch (error) {
    owner.dispose(); // release the failed mount; the shared kit geometry belongs to the asset cache
    throw error;
  }
}

async function build(owner: ReturnType<typeof createOwnedView>) {
  const [pieces, { ORIGIN }] = await Promise.all([terrainKitGeometry(), import('../../place/layout.ts')]);
  owner.cleanup(() => setTerrainKit(new Map()));
  setTerrainKit(pieces);

  // Each area its own batches: an instanced mesh culls as one, so an area behind you submits nothing.
  const areas = KIT_AREAS.map((level) => {
    const placements = loadLevelArtifact(level, definitions).placements;
    const counts = new Map<PrefabKey, number>();
    for (const p of placements) counts.set(p.prefab, (counts.get(p.prefab) ?? 0) + 1);
    const area = new Map([...counts].map(([key, n]) => [key, createPrefabBatch(key, n, owner)]));
    const used = new Map<PrefabKey, number>();
    const things = placements.map((p) => {
      const index = used.get(p.prefab) ?? 0;
      used.set(p.prefab, index + 1);
      return instantiate(
        p.prefab,
        { ...p, pos: [p.pos[0] + ORIGIN.x, p.pos[1], p.pos[2] + ORIGIN.z] },
        { owner, batch: { target: area.get(p.prefab)!, index }, still: true },
      );
    });
    return { batches: area.size, things, island: level.place === 'cliff-kit-ring-island' };
  });
  const things = areas.flatMap((a) => a.things),
    batches = areas.reduce((n, a) => n + a.batches, 0);

  // Mount-time clearance: the pieces whose solids hold Buddy when the kit mounts wait, neither drawn nor solid (an
  // instance batch draws a piece only while it is enabled), as one set until Buddy is clear of them all, then turn solid
  // for good. After that the pieces are ordinary static solids, like every other collider: the solver resolves contact
  // as it does for any wall, and where a returning player is placed is the shared return check's job
  // (src/place/pose.ts).
  const enable = (records: typeof things) =>
    liftOrWait(
      records.map((t) => ({ shapes: t.solids, on: () => t.setEnabled(true) })),
      me.body,
      { lift: false },
    );
  const clearing = enable(areas.filter((a) => !a.island).flatMap((a) => a.things));
  const island = areas.filter((a) => a.island).flatMap((a) => a.things);
  let islandClearing: ReturnType<typeof enable> | undefined;

  return {
    root: owner.root,
    /** Each frame: turns the waiting pieces solid once Buddy is clear of them all (nothing once all are solid). */
    update() {
      clearing.retry(me.body);
      if (ringIslandNear.mounted) {
        islandClearing ??= enable(island);
        islandClearing.retry(me.body);
      } else if (islandClearing) {
        for (const piece of island) piece.setEnabled(false);
        islandClearing = undefined;
      }
    },
    inspect: () => ({
      pieces: things.length,
      batches,
      waiting: clearing.waiting.length + (islandClearing?.waiting.length ?? 0),
    }),
    dispose: () => owner.dispose(),
  };
}
